#!/usr/bin/env python3.10
"""Mechanical gate for the Egg Drop answer - FIRST SLICE (G01, G03, G04 only).

# Scope

This is the first implementation slice: structure (G01), independent mass/cost
recomputation (G03) and the hard limits (G04). Rows G02 and G05-G12 are not
implemented yet and are reported as NA, so a control that violates them is
still accepted by this slice - which is exactly the red state the red-first
journal records. The full checker replaces this file.

Exit codes: 0 = PASS (answer) / all controls behaved as declared (selftest);
1 = a violation was correctly detected; 2 = infrastructure/input error or zero
selected cases (INVALID - never PASS).
"""

import argparse
import hashlib
import json
import math
import re
import sys
from pathlib import Path

SCHEMA = "egg-drop-gate-v1"
DATA_SCHEMA = "egg-drop-data-v1"
SECTION_TITLES = [
    "## 1. Концепция",
    "## 2. Спецификация",
    "## 3. Физические расчёты",
    "## 4. Оценка надёжности",
    "## 5. Альтернативы",
    "## 6. Итерации",
]
GATE_IDS = ["G%02d" % i for i in range(1, 13)]


class Invalid(Exception):
    pass


def is_num(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value)


def sha256_file(path):
    digest = hashlib.sha256()
    with open(path, "rb") as handle:
        for chunk in iter(lambda: handle.read(65536), b""):
            digest.update(chunk)
    return digest.hexdigest()


def split_sections(text):
    lines = text.splitlines()
    heads = []
    in_fence = False
    for index, line in enumerate(lines):
        if line.strip().startswith("```"):
            in_fence = not in_fence
            continue
        if not in_fence and re.match(r"^##\s+\S", line):
            heads.append((index, line.strip()))
    sections = []
    for position, (index, title) in enumerate(heads):
        end = heads[position + 1][0] if position + 1 < len(heads) else len(lines)
        sections.append({"index": position + 1, "title": title, "body": "\n".join(lines[index + 1:end])})
    return sections


def parse_answer(text):
    sections = split_sections(text)
    data = None
    problem = ""
    if len(sections) >= 2:
        match = re.search(r"^```json\s*$(.*?)^```\s*$", sections[1]["body"], re.M | re.S)
        if not match:
            problem = "no fenced json block in section 2"
        else:
            try:
                data = json.loads(match.group(1))
            except json.JSONDecodeError as exc:
                problem = "json block does not parse: %s" % exc
    return {"sections": sections, "data": data, "problem": problem}


def row(gid, status, expected, actual, source):
    return {"id": gid, "status": status, "expected": expected, "actual": actual, "source": source}


def run_gate(text):
    parsed = parse_answer(text)
    problems = []
    titles = [s["title"] for s in parsed["sections"]]
    if titles != SECTION_TITLES:
        problems.append("sections are %r" % titles)
    if parsed["problem"]:
        problems.append(parsed["problem"])
    data = parsed["data"]
    if not isinstance(data, dict):
        problems.append("data block is not an object")
    elif data.get("schema") != DATA_SCHEMA:
        problems.append("data marker is %r" % data.get("schema"))
    if problems:
        checks = [row("G01", "FAIL", "six sections + data block", "; ".join(problems), "answer.md:headings")]
        checks += [row(gid, "NA", "not evaluated", "structure gate G01 failed", "answer.md") for gid in GATE_IDS[1:]]
        return checks, "FAIL", []

    g03 = []
    g04 = []
    materials = data.get("materials")
    if not isinstance(materials, list) or not materials:
        g03.append("materials must be a non-empty list")
        materials = []
    for item in materials:
        if not isinstance(item, dict):
            g03.append("material is not an object")
            continue
        for field in ("quantity", "mass_g", "cost_usd"):
            if not is_num(item.get(field)) or item.get(field) < 0:
                g03.append("%s.%s is not a finite non-negative number" % (item.get("id"), field))
    egg_mass = data.get("egg", {}).get("mass_g")
    if not is_num(egg_mass) or egg_mass <= 0:
        g03.append("egg.mass_g is not a finite positive number")
    total_mass = sum(float(item["mass_g"]) for item in materials if is_num(item.get("mass_g")))
    total_cost = sum(float(item["cost_usd"]) for item in materials if is_num(item.get("cost_usd")))
    if is_num(egg_mass):
        total_mass += float(egg_mass)
    declared_mass = data.get("totals", {}).get("total_mass_g")
    declared_cost = data.get("totals", {}).get("total_cost_usd")
    if not is_num(declared_mass):
        g03.append("totals.total_mass_g is not a finite number (%r)" % (declared_mass,))
    elif abs(declared_mass - total_mass) > 0.1:
        g03.append("declared mass %r g != recomputed %.3f g" % (declared_mass, total_mass))
    if not is_num(declared_cost):
        g03.append("totals.total_cost_usd is not a finite number (%r)" % (declared_cost,))
    elif abs(declared_cost - total_cost) > 0.01:
        g03.append("declared cost %r $ != recomputed %.3f $" % (declared_cost, total_cost))

    if total_mass > 500.0:
        g04.append("total mass %.3f g > 500 g" % total_mass)
    if total_cost > 5.0 + 1e-9:
        g04.append("total cost %.4f $ > 5.00 $" % total_cost)
    build = data.get("totals", {}).get("build_time_min")
    if is_num(build) and build > 30.0:
        g04.append("build time %r min > 30 min" % build)
    sides = []
    for axis in ("length", "width", "height"):
        value = data.get("outer_dimensions_mm", {}).get(axis)
        if not is_num(value):
            g04.append("outer_dimensions_mm.%s is not a number" % axis)
        else:
            sides.append(float(value))
            if value > 300.0:
                g04.append("outer %s %r mm > 300 mm" % (axis, value))
    if len(sides) == 3:
        volume = sides[0] * sides[1] * sides[2] / 1e9
        if volume > 0.02 + 1e-12:
            g04.append("bounding volume %.6f m3 > 0.02 m3" % volume)

    findings = {"G01": [], "G03": g03, "G04": g04}
    checks = []
    for gid in GATE_IDS:
        if gid not in findings:
            checks.append(row(gid, "NA", "not implemented in the first slice", "row not implemented yet", "answer.md"))
            continue
        status = "FAIL" if findings[gid] else "PASS"
        actual = "; ".join(findings[gid]) if findings[gid] else "all assertions of this row hold"
        checks.append(row(gid, status, "slice check %s" % gid, actual, "answer.md"))
    gate = "FAIL" if any(item["status"] == "FAIL" for item in checks) else "PASS"
    return checks, gate, []


def resolve(repo, value):
    path = Path(value)
    return path if path.is_absolute() else Path(repo) / path


def write_report(path, report):
    target = Path(path)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(json.dumps(report, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


def skeleton(suite, selected):
    return {
        "schema": SCHEMA,
        "suite": suite,
        "selected_cases": selected,
        "input_hashes": {},
        "checks": [],
        "cases": [],
        "gate": "FAIL",
        "diagnostics": [],
    }


def run_answer(args):
    repo = Path(args.repo)
    answer_path = resolve(repo, args.answer)
    if not answer_path.is_file():
        raise Invalid("answer file not found: %s" % answer_path)
    report = skeleton("answer", 1)
    report["input_hashes"][str(answer_path)] = sha256_file(answer_path)
    checks, gate, diagnostics = run_gate(answer_path.read_text(encoding="utf-8"))
    report["checks"] = checks
    report["gate"] = gate
    report["diagnostics"] = diagnostics
    write_report(args.report, report)
    return 0 if gate == "PASS" else 1


def run_selftest(args):
    repo = Path(args.repo)
    fixtures_dir = resolve(repo, args.fixtures)
    manifest_path = fixtures_dir / "manifest.json"
    if not manifest_path.is_file():
        raise Invalid("manifest not found: %s" % manifest_path)
    manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    declared = manifest.get("cases") or []
    selected = declared if args.case == "all-declared" else [c for c in declared if c.get("case") == args.case]
    if not selected:
        raise Invalid("zero cases selected for --case %r" % args.case)
    report = skeleton("selftest", len(selected))
    report["input_hashes"][str(manifest_path)] = sha256_file(manifest_path)
    failures = 0
    for item in selected:
        answer_path = resolve(repo, str(Path(args.fixtures) / item["path"]))
        if not answer_path.is_file():
            raise Invalid("control answer not found: %s" % answer_path)
        report["input_hashes"][str(answer_path)] = sha256_file(answer_path)
        checks, gate, _diagnostics = run_gate(answer_path.read_text(encoding="utf-8"))
        observed = [r["id"] for r in checks if r["status"] == "FAIL"]
        expected_status = item.get("expected_status")
        expected_id = item.get("expected_id")
        if expected_status == "PASS":
            ok = gate == "PASS" and not observed
        else:
            ok = gate == "FAIL" and observed == [expected_id]
        if not ok:
            failures += 1
            report["diagnostics"].append(
                "case %s: expected %s at %s, observed %s %s"
                % (item.get("case"), expected_status, expected_id, gate, observed)
            )
        report["cases"].append(
            {
                "case": item.get("case"),
                "expected_status": expected_status,
                "expected_id": expected_id,
                "observed_status": gate,
                "observed_ids": observed,
                "ok": ok,
            }
        )
    report["gate"] = "PASS" if failures == 0 else "FAIL"
    write_report(args.report, report)
    return 0 if failures == 0 else 1


def main(argv=None):
    parser = argparse.ArgumentParser(description="Egg Drop mechanical gate (first slice)")
    parser.add_argument("--repo", required=True)
    parser.add_argument("--suite", required=True, choices=["selftest", "answer"])
    parser.add_argument("--case", required=True)
    parser.add_argument("--fixtures")
    parser.add_argument("--answer")
    parser.add_argument("--report", required=True)
    args = parser.parse_args(argv)
    try:
        if args.suite == "answer":
            if not args.answer:
                raise Invalid("--answer is required for --suite answer")
            return run_answer(args)
        if not args.fixtures:
            raise Invalid("--fixtures is required for --suite selftest")
        return run_selftest(args)
    except Invalid as exc:
        report = skeleton(args.suite, 0)
        report["diagnostics"] = ["INVALID: %s" % exc]
        write_report(args.report, report)
        sys.stderr.write("INVALID: %s\n" % exc)
        return 2


if __name__ == "__main__":
    sys.exit(main())

